    """
    prime_fib returns n-th number that is a Fibonacci number and it's also prime.
    """
    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, isqrt(num) + 1):
            if num % i == 0:
                return False
        return True

    def fibonacci_numbers():
        a, b = 0, 1
        while True:
            yield b
            a, b = b, a + b

    count = 0
    for fib in fibonacci_numbers():
        if is_prime(fib):
            count += 1
            if count == n:
                return fib
